  const target = withDeclaredSecrets(stubText, secretNames)
    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
  const path = join(root, SCHEDULER_WORKFLOW);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;

